import numpy as np
from sklearn import svm
from sklearn.datasets import make_classification, make_regression


def measure(make_xy, make_est):
    X, y = make_xy()
    try:
        pred_inf = make_est(np.inf).fit(X, y).predict(X)
    except Exception:
        # C=inf rejected by parameter validation -> no predictions returned
        return 1.0, float("nan")
    try:
        pred_ref = make_est(1e10).fit(X, y).predict(X)
    except Exception:
        return 0.0, float("nan")
    return 0.0, (1.0 if np.allclose(pred_inf, pred_ref, rtol=1e-5, atol=1e-8) else 0.0)


rej, match = measure(lambda: make_classification(random_state=0), lambda c: svm.SVC(C=c))
probe("svc_inf_rejected", rej)
probe("svc_inf_matches_C_1e10", match)

rej, match = measure(lambda: make_regression(random_state=0), lambda c: svm.SVR(C=c))
probe("svr_inf_rejected", rej)
probe("svr_inf_matches_C_1e10", match)

